const JST_OFFSET_MS = 9 * 60 * 60 * 1000;
const nowJST = new Date(Date.now() + JST_OFFSET_MS);
const dow = nowJST.getUTCDay(); // JST換算後のDateなのでgetUTCDay()がJSTの曜日になる(0=日,1=月,...,6=土)

let templateId = null;
if (dow === 1) templateId = 1; // 月: 星座別タイミング型
else if (dow === 3) templateId = 2; // 水: 共感型
else if (dow === 5) templateId = 3; // 金: ランキング型(星座)
else if (dow === 0) {
  // 日: MBTI/本命星/比較型(4〜8)を週替わりでローテーション
  const rotation = [4, 5, 6, 7, 8];
  const daysSinceEpoch = Math.floor(nowJST.getTime() / (24 * 60 * 60 * 1000));
  const weekNum = Math.floor(daysSinceEpoch / 7);
  templateId = rotation[weekNum % rotation.length];
}
// 火・木・土は定期テンプレートなし(templateIdはnullのまま)

if (templateId === null) {
  if ($mode === 'manual') {
    // 手動実行(Execute workflow)時は、動作確認のため曜日を無視してテンプレート1を強制的に使う。
    // 定期実行(スケジュールトリガー)の場合のみ、対象日以外は何もしない挙動を維持する。
    templateId = 1;
  } else {
    return []; // 今日は対象日ではない。後続ノードは空配列を受けて何もしない
  }
}

return [{
  json: {
    template_id: templateId,
    template_name: TEMPLATES[templateId].name,
    template_structure: TEMPLATES[templateId].structure
  }
}];

